DROP DATABASE IF EXISTS qwikbite;
CREATE DATABASE IF NOT EXISTS qwikbite CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE qwikbite;

CREATE TABLE food_courts(id INT AUTO_INCREMENT PRIMARY KEY,court_name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,register_number VARCHAR(40) NOT NULL UNIQUE,full_name VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL,password_hash VARCHAR(255) NOT NULL,account_type ENUM('STUDENT','FACULTY','STAFF') NOT NULL DEFAULT 'STUDENT',active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE shops(id INT AUTO_INCREMENT PRIMARY KEY,court_id INT NOT NULL,shop_name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,is_open BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(court_id) REFERENCES food_courts(id));
CREATE TABLE bitemates(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE menu_items(id INT AUTO_INCREMENT PRIMARY KEY,shop_id INT NOT NULL,item_name VARCHAR(120) NOT NULL,description VARCHAR(255),price DECIMAL(10,2) NOT NULL,stock_qty INT NOT NULL DEFAULT 50,available BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(shop_id) REFERENCES shops(id),CHECK(price>=0));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,shop_id INT NOT NULL,building ENUM('TP1','TP2','UB') NOT NULL,floor_number INT NOT NULL,room_number VARCHAR(20) NOT NULL,subtotal DECIMAL(10,2) NOT NULL,delivery_fee DECIMAL(10,2) NOT NULL,total_amount DECIMAL(10,2) NOT NULL,status ENUM('PLACED','ACCEPTED','READY','ASSIGNED','PICKED_UP','DELIVERED','REJECTED','CANCELLED') NOT NULL DEFAULT 'PLACED',delivery_id INT NULL,delivery_status ENUM('WAITING','ACCEPTED','ON_WAY_TO_PICKUP','PICKED_UP','OUT_FOR_DELIVERY','DELIVERED') NOT NULL DEFAULT 'WAITING',delivery_photo LONGBLOB NULL,delivery_photo_name VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id),FOREIGN KEY(shop_id) REFERENCES shops(id),FOREIGN KEY(delivery_id) REFERENCES bitemates(id),CHECK(floor_number>=0));
CREATE TABLE delivery_declines(order_id INT NOT NULL,mate_id INT NOT NULL,declined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(order_id,mate_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(mate_id) REFERENCES bitemates(id) ON DELETE CASCADE);
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,menu_item_id INT NOT NULL,item_name VARCHAR(120) NOT NULL,unit_price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(menu_item_id) REFERENCES menu_items(id),CHECK(quantity>0));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL UNIQUE,method ENUM('CASH_ON_DELIVERY','UPI_ON_DELIVERY') NOT NULL,status ENUM('PENDING','PAID') NOT NULL DEFAULT 'PENDING',amount DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
